import { describe, expect, it } from 'vitest';
import spec from '../../../fixtures/ats_cases.json';
import { evaluateFit } from '../domain/ats';

// fixtures/ats_cases.json is generated by the Python engine (python fixtures/generate.py).
describe('TypeScript ATS engine matches the Python MCP server', () => {
  for (const c of spec.cases) {
    it(c.name, () => {
      const got = evaluateFit(c.candidate, c.job, c.languages, c.work_authorized, spec.today);
      expect(got).toEqual(c.expected);
    });
  }
});
